<script setup lang="ts">
import {title as displayTitle,sourceName,indicator,utc,time as beijingTime,duration,http} from '../presentation/zh';
import {ref,onMounted} from 'vue';import {post,safeArticleUrl} from '../api/client';
const props=defineProps<{token:string}>();const rows=ref<Record<string,any>[]>([]),detail=ref<Record<string,any>>(),rules=ref<Record<string,any>[]>([]),error=ref(''),page=ref(0);
const evidenceId=ref(''),claim=ref(''),excerpt=ref(''),reason=ref(''),actor=ref(''),notice=ref('');
function decode(v:any){try{return JSON.parse(v?.value??v)}catch{return v}}
async function act(path:string,body:any){try{await post(path,props.token,body);notice.value='已保存实际审核记录，原始证据与消息均保留';if(detail.value)await open(detail.value.case.id);}catch(e){error.value=(e as Error).message;}}
async function load(){try{rows.value=await post('/governance/cases',props.token,{page:page.value});rules.value=await post('/governance/rules',props.token);}catch{error.value='事件治理数据暂不可用';}}
async function open(id:string){try{detail.value=await post('/governance/cases/'+id,props.token);}catch{error.value='事件聚类详情暂不可用';}}
onMounted(()=>void load());
</script>
<template><section class="panel feed"><h2>金融事件质量治理</h2><p>原始消息、宏观观测与研究候选分别管理。当前文章组不等于已核实独立经济事件；规则优先级不是收益预测。</p><p v-if="error">{{error}}</p><button @click="load">刷新实际研究候选</button><button :disabled="page===0" @click="page--;load()">上一页</button><button :disabled="rows.length<50" @click="page++;load()">下一页</button><p v-if="!rows.length">暂无真实数据</p><article v-for="r in rows" :key="r.id"><h3>{{displayTitle({original_title:r.title,source_id:r.source_id}).text}}</h3><details><summary>查看候选组原文标题</summary><p>{{r.title}}</p></details><p>研究优先级 {{r.priority}} · 原始消息 {{r.message_count}} · {{r.verification==='VERIFIED'?'已核实':'待审核'}} · 同原文候选组</p><button @click="open(r.id)">查看聚类与来源依赖</button></article><section v-if="detail"><h3>聚类详情</h3><p>{{detail.case.title}} · 所有原始消息与证据均保留</p><article v-for="r in detail.messages" :key="r.event_id"><p>{{r.original_title}} · {{r.dependency}}</p><pre>{{decode(r.topics)}} · {{decode(r.basis)}}</pre><p>证据 {{r.evidence_id}}</p><code>{{r.raw_content_hash}}</code><p><a v-if="safeArticleUrl(r.source_url)" :href="r.source_url" target="_blank" rel="noopener noreferrer">查看原始来源</a></p></article><p v-if="!detail.facts.length">事实证据不足：尚无已审核事实</p><article v-for="f in detail.facts" :key="f.id"><h4>{{f.claim}}</h4><blockquote>{{f.excerpt}}</blockquote><p>证据 {{f.evidence_id}} · 字符定位 {{f.start_offset}} 至 {{f.end_offset}} · {{f.status==='VERIFIED'?'人工已核实':f.status==='CONFLICT'?'证据存在冲突':f.status==='REJECTED'?'已否决':'待审核'}}</p><div class="filters"><button v-for="[code,label] in [['VERIFIED','审核此条事实'],['CONFLICT','记录证据冲突'],['REJECTED','否决此条事实']]" :key="code" :disabled="!reason||!actor" @click="act('/governance/facts/'+f.id+'/review',{decision:code,reason,actor})">{{label}}</button></div></article><h4>添加有来源的事实候选</h4><input v-model="evidenceId" placeholder="当前候选组的真实证据 ID"><textarea v-model="claim" placeholder="事实主张（保持待人工审核）"/><textarea v-model="excerpt" placeholder="原始响应中的逐字摘录"/><button :disabled="!evidenceId||!claim||!excerpt" @click="act('/governance/cases/'+detail.case.id+'/facts',{evidenceId,claim,excerpt})">保存待审核事实</button><input v-model="actor" placeholder="实际审核人"><textarea v-model="reason" placeholder="审核理由与核验依据（至少10字）"/><p>{{notice}}</p><p v-if="!detail.hypotheses.length">尚无有证据的影响假设</p><article v-for="h in detail.hypotheses" :key="h.id"><p>{{h.mechanism}}</p><p>影响方向 {{h.direction==='POSITIVE'?'正面假设':h.direction==='NEGATIVE'?'负面假设':'尚不确定'}} · 不确定性 {{h.uncertainty}} · 不是已核实事实</p></article></section><details><summary>当前可配置分类规则与版本</summary><p v-for="r in rules" :key="r.id">{{r.display_name_zh}} · 版本 {{r.version}} · 分类权重 {{r.weight}}</p></details></section></template>

<style scoped>pre{white-space:pre-wrap;overflow-wrap:anywhere}p,code,blockquote{overflow-wrap:anywhere}textarea{width:100%;min-height:60px;background:#111f30;color:#dbe4ef;border:1px solid #324258;margin:8px 0;padding:10px}input{max-width:100%}</style>
